    for (final leg in const [
      'TESTFLIGHT',
      'PLAY',
      'PUBDEV',
      'CLI',
      'WEBSITE',
      'ADDIN',
    ])
      'LEG_$leg': legResults[leg.toLowerCase()] ?? 'skipped',
